/**
 * Database schema. Every tenant-owned table has `tenant_id` and is protected by RLS
 * (see migrations/9999_rls.sql generated by src/db/rls.ts).
 */
import { sql } from 'drizzle-orm';
import {
  bigserial,
  boolean,
  date,
  index,
  integer,
  jsonb,
  numeric,
  pgTable,
  primaryKey,
  text,
  time,
  timestamp,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';

const id = () => uuid('id').primaryKey().defaultRandom();
const ts = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });
const createdAt = () => ts('created_at').notNull().defaultNow();
const updatedAt = () => ts('updated_at').notNull().defaultNow().$onUpdate(() => new Date());
const money = (name: string) => numeric(name, { precision: 14, scale: 2, mode: 'number' });
const tenantId = () =>
  uuid('tenant_id')
    .notNull()
    .references(() => tenants.id, { onDelete: 'cascade' });

/* ======================= Platform ======================= */

export interface TenantSettings {
  directoryShowJoinDate: boolean;
  communityPostingMode: 'EVERYONE' | 'GRANTED_ONLY' | 'STAFF_ONLY';
  communityEngagementEnabled: boolean;
  medicalAnnualLimit: number;
  overtimeThresholdMinutes: number;
  payrollWorkingHoursBased: boolean;
}

export const DEFAULT_TENANT_SETTINGS: TenantSettings = {
  directoryShowJoinDate: false,
  communityPostingMode: 'GRANTED_ONLY',
  communityEngagementEnabled: true,
  medicalAnnualLimit: 50000,
  overtimeThresholdMinutes: 30,
  payrollWorkingHoursBased: true,
};

export const tenants = pgTable('tenants', {
  id: id(),
  name: text('name').notNull(),
  slug: text('slug').notNull().unique(),
  status: text('status', { enum: ['ACTIVE', 'SUSPENDED'] }).notNull().default('ACTIVE'),
  timezone: text('timezone').notNull().default('Asia/Karachi'),
  currency: text('currency').notNull().default('PKR'),
  settings: jsonb('settings').$type<TenantSettings>().notNull().default(DEFAULT_TENANT_SETTINGS),
  employeeSeq: integer('employee_seq').notNull().default(0),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

/* ======================= Identity & access (A1) ======================= */

export const users = pgTable(
  'users',
  {
    id: id(),
    tenantId: tenantId(),
    email: text('email').notNull(),
    passwordHash: text('password_hash'),
    status: text('status', { enum: ['INVITED', 'ACTIVE', 'DISABLED'] }).notNull().default('INVITED'),
    employeeId: uuid('employee_id'),
    failedLoginCount: integer('failed_login_count').notNull().default(0),
    lockedUntil: ts('locked_until'),
    lastLoginAt: ts('last_login_at'),
    passwordChangedAt: ts('password_changed_at'),
    mustChangePassword: boolean('must_change_password').notNull().default(false),
    canPost: boolean('can_post').notNull().default(false), // G1 posting grant
    tokenVersion: integer('token_version').notNull().default(0), // bump to revoke all access tokens
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex('users_tenant_email_uq').on(t.tenantId, t.email), index('users_employee_idx').on(t.employeeId)],
);

export const userRoles = pgTable(
  'user_roles',
  {
    tenantId: tenantId(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    role: text('role').notNull(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.role] })],
);

export const rolePermissions = pgTable(
  'role_permissions',
  {
    tenantId: tenantId(),
    role: text('role').notNull(),
    permission: text('permission').notNull(),
  },
  (t) => [primaryKey({ columns: [t.tenantId, t.role, t.permission] })],
);

export const refreshTokens = pgTable(
  'refresh_tokens',
  {
    id: id(),
    tenantId: tenantId(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    familyId: uuid('family_id').notNull(),
    tokenHash: text('token_hash').notNull().unique(),
    expiresAt: ts('expires_at').notNull(),
    revokedAt: ts('revoked_at'),
    replacedById: uuid('replaced_by_id'),
    ip: text('ip'),
    userAgent: text('user_agent'),
    createdAt: createdAt(),
  },
  (t) => [index('refresh_tokens_user_idx').on(t.userId)],
);

export const userTokens = pgTable('user_tokens', {
  id: id(),
  tenantId: tenantId(),
  userId: uuid('user_id')
    .notNull()
    .references(() => users.id, { onDelete: 'cascade' }),
  purpose: text('purpose', { enum: ['INVITE', 'PASSWORD_RESET'] }).notNull(),
  tokenHash: text('token_hash').notNull().unique(),
  expiresAt: ts('expires_at').notNull(),
  usedAt: ts('used_at'),
  createdByUserId: uuid('created_by_user_id'),
  createdAt: createdAt(),
});

/* ======================= Files ======================= */

export const files = pgTable('files', {
  id: id(),
  tenantId: tenantId(),
  storageKey: text('storage_key').notNull(),
  originalName: text('original_name').notNull(),
  mimeType: text('mime_type').notNull(),
  size: integer('size').notNull(),
  sha256: text('sha256').notNull(),
  uploadedByUserId: uuid('uploaded_by_user_id'),
  createdAt: createdAt(),
});

/* ======================= Organisation (B7) ======================= */

export const departments = pgTable(
  'departments',
  {
    id: id(),
    tenantId: tenantId(),
    name: text('name').notNull(),
    code: text('code').notNull(),
    headEmployeeId: uuid('head_employee_id'),
    foodAllowanceEnabled: boolean('food_allowance_enabled').notNull().default(false),
    paidOvertimeEnabled: boolean('paid_overtime_enabled').notNull().default(false),
    isActive: boolean('is_active').notNull().default(true),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex('departments_tenant_code_uq').on(t.tenantId, t.code)],
);

export const levels = pgTable(
  'levels',
  {
    id: id(),
    tenantId: tenantId(),
    departmentId: uuid('department_id')
      .notNull()
      .references(() => departments.id),
    code: text('code').notNull(),
    rank: integer('rank').notNull(),
    title: text('title').notNull(),
    description: text('description'),
    defaultSalary: money('default_salary').notNull(),
    minSalary: money('min_salary'),
    maxSalary: money('max_salary'),
    isActive: boolean('is_active').notNull().default(true),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex('levels_dept_code_uq').on(t.departmentId, t.code)],
);

export const workSchedules = pgTable('work_schedules', {
  id: id(),
  tenantId: tenantId(),
  name: text('name').notNull(),
  startTime: time('start_time').notNull(),
  endTime: time('end_time').notNull(),
  breakMinutes: integer('break_minutes').notNull().default(60),
  graceMinutes: integer('grace_minutes').notNull().default(15),
  workingDays: jsonb('working_days').$type<number[]>().notNull().default([1, 2, 3, 4, 5]),
  isDefault: boolean('is_default').notNull().default(false),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

/* ======================= Employees (B1–B8) ======================= */

export const employees = pgTable(
  'employees',
  {
    id: id(),
    tenantId: tenantId(),
    employeeCode: text('employee_code').notNull(),
    userId: uuid('user_id'),
    fullName: text('full_name').notNull(),
    email: text('email').notNull(),
    cnic: text('cnic'),
    fatherName: text('father_name'),
    fatherCnic: text('father_cnic'),
    bloodGroup: text('blood_group'),
    emergencyContact: text('emergency_contact'),
    contactNo: text('contact_no'),
    dateOfBirth: date('date_of_birth', { mode: 'string' }),
    avatarFileId: uuid('avatar_file_id'),
    departmentId: uuid('department_id')
      .notNull()
      .references(() => departments.id),
    levelId: uuid('level_id')
      .notNull()
      .references(() => levels.id),
    designation: text('designation').notNull(),
    reportingManagerId: uuid('reporting_manager_id'),
    hierarchyTier: text('hierarchy_tier').notNull().default('MEMBER'),
    joiningDate: date('joining_date', { mode: 'string' }).notNull(),
    exitDate: date('exit_date', { mode: 'string' }),
    employmentStatus: text('employment_status', { enum: ['ACTIVE', 'INACTIVE', 'RESIGNED', 'TERMINATED'] })
      .notNull()
      .default('ACTIVE'),
    basicSalary: money('basic_salary').notNull(),
    workScheduleId: uuid('work_schedule_id').references(() => workSchedules.id),
    onboardingCompletedAt: ts('onboarding_completed_at'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex('employees_tenant_code_uq').on(t.tenantId, t.employeeCode),
    uniqueIndex('employees_tenant_email_uq').on(t.tenantId, t.email),
    index('employees_dept_idx').on(t.departmentId),
    index('employees_status_idx').on(t.tenantId, t.employmentStatus),
  ],
);

/** B8 – every position an employee has held. */
export const employeePositions = pgTable(
  'employee_positions',
  {
    id: id(),
    tenantId: tenantId(),
    employeeId: uuid('employee_id')
      .notNull()
      .references(() => employees.id, { onDelete: 'cascade' }),
    departmentId: uuid('department_id').notNull(),
    levelId: uuid('level_id').notNull(),
    designation: text('designation').notNull(),
    salary: money('salary').notNull(),
    startDate: date('start_date', { mode: 'string' }).notNull(),
    endDate: date('end_date', { mode: 'string' }),
    changeType: text('change_type', { enum: ['JOINED', 'PROMOTED', 'TRANSFERRED', 'ADJUSTED'] }).notNull(),
    notes: text('notes'),
    recordedByUserId: uuid('recorded_by_user_id'),
    createdAt: createdAt(),
  },
  (t) => [index('positions_employee_idx').on(t.employeeId)],
);

export const employeeDocuments = pgTable(
  'employee_documents',
  {
    id: id(),
    tenantId: tenantId(),
    employeeId: uuid('employee_id')
      .notNull()
      .references(() => employees.id, { onDelete: 'cascade' }),
    fileId: uuid('file_id')
      .notNull()
      .references(() => files.id),
    category: text('category').notNull(),
    title: text('title'),
    source: text('source', { enum: ['EMPLOYEE', 'HR'] }).notNull(),
    uploadedByUserId: uuid('uploaded_by_user_id'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index('emp_docs_employee_idx').on(t.employeeId)],
);

export const teams = pgTable('teams', {
  id: id(),
  tenantId: tenantId(),
  name: text('name').notNull(),
  departmentId: uuid('department_id')
    .notNull()
    .references(() => departments.id),
  leadEmployeeId: uuid('lead_employee_id')
    .notNull()
    .references(() => employees.id),
  isActive: boolean('is_active').notNull().default(true),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const teamMembers = pgTable(
  'team_members',
  {
    tenantId: tenantId(),
    teamId: uuid('team_id')
      .notNull()
      .references(() => teams.id, { onDelete: 'cascade' }),
    employeeId: uuid('employee_id')
      .notNull()
      .references(() => employees.id, { onDelete: 'cascade' }),
    addedAt: createdAt(),
  },
  // An employee belongs to at most one team (A1 rule).
  (t) => [primaryKey({ columns: [t.teamId, t.employeeId] }), uniqueIndex('team_members_employee_uq').on(t.employeeId)],
);

/* ======================= Generic approval columns ======================= */

const approvalColumns = () => ({
  status: text('status', { enum: ['PENDING', 'APPROVED', 'REJECTED', 'CANCELLED'] }).notNull().default('PENDING'),
  currentStep: text('current_step'),
});

export const teamTransferRequests = pgTable('team_transfer_requests', {
  id: id(),
  tenantId: tenantId(),
  employeeId: uuid('employee_id')
    .notNull()
    .references(() => employees.id),
  fromTeamId: uuid('from_team_id').references(() => teams.id),
  toTeamId: uuid('to_team_id')
    .notNull()
    .references(() => teams.id),
  requestedByEmployeeId: uuid('requested_by_employee_id').notNull(),
  reason: text('reason'),
  ...approvalColumns(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const resignations = pgTable('resignations', {
  id: id(),
  tenantId: tenantId(),
  employeeId: uuid('employee_id')
    .notNull()
    .references(() => employees.id),
  reason: text('reason').notNull(),
  requestedLastWorkingDate: date('requested_last_working_date', { mode: 'string' }).notNull(),
  approvedLastWorkingDate: date('approved_last_working_date', { mode: 'string' }),
  ...approvalColumns(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

/** Full approval history for every workflow (H1, F5). */
export const approvalActions = pgTable(
  'approval_actions',
  {
    id: id(),
    tenantId: tenantId(),
    workflow: text('workflow').notNull(),
    entityId: uuid('entity_id').notNull(),
    step: text('step'),
    action: text('action', { enum: ['SUBMIT', 'APPROVE', 'REJECT', 'CANCEL'] }).notNull(),
    actorUserId: uuid('actor_user_id'),
    comment: text('comment'),
    createdAt: createdAt(),
  },
  (t) => [index('approval_actions_entity_idx').on(t.workflow, t.entityId)],
);

/* ======================= Attendance (C1, C2) ======================= */

export const attendanceDevices = pgTable('attendance_devices', {
  id: id(),
  tenantId: tenantId(),
  name: text('name').notNull(),
  apiKeyHash: text('api_key_hash').notNull().unique(),
  apiKeyPrefix: text('api_key_prefix').notNull(),
  lastSeenAt: ts('last_seen_at'),
  isActive: boolean('is_active').notNull().default(true),
  createdAt: createdAt(),
});

export const attendancePunches = pgTable(
  'attendance_punches',
  {
    id: id(),
    tenantId: tenantId(),
    employeeId: uuid('employee_id')
      .notNull()
      .references(() => employees.id, { onDelete: 'cascade' }),
    punchedAt: ts('punched_at').notNull(),
    type: text('type'),
    source: text('source', { enum: ['DEVICE', 'IMPORT', 'MANUAL', 'CORRECTION'] }).notNull(),
    deviceId: uuid('device_id'),
    note: text('note'),
    createdAt: createdAt(),
  },
  (t) => [
    index('punches_employee_time_idx').on(t.employeeId, t.punchedAt),
    uniqueIndex('punches_dedupe_uq').on(t.employeeId, t.punchedAt, t.source),
  ],
);

export const attendanceDays = pgTable(
  'attendance_days',
  {
    id: id(),
    tenantId: tenantId(),
    employeeId: uuid('employee_id')
      .notNull()
      .references(() => employees.id, { onDelete: 'cascade' }),
    date: date('date', { mode: 'string' }).notNull(),
    checkIn: ts('check_in'),
    checkOut: ts('check_out'),
    breakMinutes: integer('break_minutes').notNull().default(0),
    workedMinutes: integer('worked_minutes').notNull().default(0),
    scheduledMinutes: integer('scheduled_minutes').notNull().default(0),
    lateMinutes: integer('late_minutes').notNull().default(0),
    overtimeMinutes: integer('overtime_minutes').notNull().default(0),
    status: text('status').notNull(),
    skippedBreak: boolean('skipped_break').notNull().default(false),
    earlyLeave: boolean('early_leave').notNull().default(false),
    workFromHome: boolean('work_from_home').notNull().default(false),
    notes: text('notes'),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex('attendance_days_emp_date_uq').on(t.employeeId, t.date), index('attendance_days_date_idx').on(t.tenantId, t.date)],
);

export const attendanceCorrections = pgTable('attendance_corrections', {
  id: id(),
  tenantId: tenantId(),
  employeeId: uuid('employee_id')
    .notNull()
    .references(() => employees.id),
  date: date('date', { mode: 'string' }).notNull(),
  checkIn: time('check_in'),
  checkOut: time('check_out'),
  reason: text('reason').notNull(),
  ...approvalColumns(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const overtimeRecords = pgTable(
  'overtime_records',
  {
    id: id(),
    tenantId: tenantId(),
    employeeId: uuid('employee_id')
      .notNull()
      .references(() => employees.id),
    date: date('date', { mode: 'string' }).notNull(),
    minutes: integer('minutes').notNull(),
    approvedMinutes: integer('approved_minutes'),
    workDescription: text('work_description'),
    ...approvalColumns(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex('overtime_emp_date_uq').on(t.employeeId, t.date)],
);

export const compensationRequests = pgTable('compensation_requests', {
  id: id(),
  tenantId: tenantId(),
  employeeId: uuid('employee_id')
    .notNull()
    .references(() => employees.id),
  type: text('type', { enum: ['PAID', 'HALF_DAY'] }).notNull(),
  minutes: integer('minutes').notNull(),
  date: date('date', { mode: 'string' }),
  reason: text('reason').notNull(),
  payrollRunId: uuid('payroll_run_id'),
  ...approvalColumns(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

/* ======================= Leave, holidays, calendar (C3–C5) ======================= */

export const leaveTypes = pgTable(
  'leave_types',
  {
    id: id(),
    tenantId: tenantId(),
    code: text('code').notNull(),
    name: text('name').notNull(),
    annualAllowance: numeric('annual_allowance', { precision: 5, scale: 1, mode: 'number' }).notNull(),
    isPaid: boolean('is_paid').notNull().default(true),
    derivedFromOvertime: boolean('derived_from_overtime').notNull().default(false),
    color: text('color').notNull().default('#1e3a8a'),
    isActive: boolean('is_active').notNull().default(true),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex('leave_types_tenant_code_uq').on(t.tenantId, t.code)],
);

export const leaveAllocations = pgTable('leave_allocations', {
  id: id(),
  tenantId: tenantId(),
  employeeId: uuid('employee_id')
    .notNull()
    .references(() => employees.id, { onDelete: 'cascade' }),
  leaveTypeId: uuid('leave_type_id')
    .notNull()
    .references(() => leaveTypes.id),
  year: integer('year').notNull(),
  days: numeric('days', { precision: 5, scale: 1, mode: 'number' }).notNull(),
  reason: text('reason').notNull(),
  createdByUserId: uuid('created_by_user_id'),
  createdAt: createdAt(),
});

export const leaveRequests = pgTable(
  'leave_requests',
  {
    id: id(),
    tenantId: tenantId(),
    employeeId: uuid('employee_id')
      .notNull()
      .references(() => employees.id),
    leaveTypeId: uuid('leave_type_id')
      .notNull()
      .references(() => leaveTypes.id),
    startDate: date('start_date', { mode: 'string' }).notNull(),
    endDate: date('end_date', { mode: 'string' }).notNull(),
    halfDay: boolean('half_day').notNull().default(false),
    days: numeric('days', { precision: 5, scale: 1, mode: 'number' }).notNull(),
    reason: text('reason').notNull(),
    ...approvalColumns(),
    cancellationStatus: text('cancellation_status', { enum: ['REQUESTED', 'APPROVED', 'REJECTED'] }),
    cancellationReason: text('cancellation_reason'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index('leave_requests_emp_idx').on(t.employeeId, t.startDate)],
);

export const holidays = pgTable(
  'holidays',
  {
    id: id(),
    tenantId: tenantId(),
    name: text('name').notNull(),
    date: date('date', { mode: 'string' }).notNull(),
    type: text('type', { enum: ['PUBLIC', 'COMPANY'] }).notNull(),
    departmentId: uuid('department_id').references(() => departments.id),
    createdAt: createdAt(),
  },
  (t) => [index('holidays_date_idx').on(t.tenantId, t.date)],
);

export const calendarEvents = pgTable('calendar_events', {
  id: id(),
  tenantId: tenantId(),
  title: text('title').notNull(),
  description: text('description'),
  startDate: date('start_date', { mode: 'string' }).notNull(),
  endDate: date('end_date', { mode: 'string' }).notNull(),
  visibility: text('visibility', { enum: ['COMPANY', 'DEPARTMENT'] }).notNull(),
  departmentId: uuid('department_id').references(() => departments.id),
  createdByUserId: uuid('created_by_user_id'),
  createdAt: createdAt(),
});

/* ======================= Payroll (D1–D4) ======================= */

export const salaryComponents = pgTable('salary_components', {
  id: id(),
  tenantId: tenantId(),
  kind: text('kind', { enum: ['ALLOWANCE', 'DEDUCTION'] }).notNull(),
  code: text('code').notNull(),
  label: text('label').notNull(),
  amount: money('amount').notNull(),
  isPercentOfBasic: boolean('is_percent_of_basic').notNull().default(false),
  employeeId: uuid('employee_id').references(() => employees.id, { onDelete: 'cascade' }),
  departmentId: uuid('department_id').references(() => departments.id),
  isActive: boolean('is_active').notNull().default(true),
  createdAt: createdAt(),
});

export const payrollRuns = pgTable(
  'payroll_runs',
  {
    id: id(),
    tenantId: tenantId(),
    period: text('period').notNull(), // YYYY-MM
    status: text('status', { enum: ['DRAFT', 'PENDING_APPROVAL', 'APPROVED', 'REJECTED', 'PAID'] })
      .notNull()
      .default('DRAFT'),
    currentStep: text('current_step'),
    totalGross: money('total_gross').notNull().default(0),
    totalNet: money('total_net').notNull().default(0),
    employeeCount: integer('employee_count').notNull().default(0),
    processedByUserId: uuid('processed_by_user_id'),
    processedAt: ts('processed_at'),
    paidAt: ts('paid_at'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex('payroll_runs_tenant_period_uq').on(t.tenantId, t.period)],
);

export interface PayslipLine {
  kind: 'EARNING' | 'ALLOWANCE' | 'BONUS' | 'DEDUCTION';
  code: string;
  label: string;
  amount: number;
  manual?: boolean;
}

export const payslips = pgTable(
  'payslips',
  {
    id: id(),
    tenantId: tenantId(),
    payrollRunId: uuid('payroll_run_id')
      .notNull()
      .references(() => payrollRuns.id, { onDelete: 'cascade' }),
    employeeId: uuid('employee_id')
      .notNull()
      .references(() => employees.id),
    period: text('period').notNull(),
    basicSalary: money('basic_salary').notNull(),
    scheduledMinutes: integer('scheduled_minutes').notNull(),
    payableMinutes: integer('payable_minutes').notNull(),
    earnedBasic: money('earned_basic').notNull(),
    totalAllowances: money('total_allowances').notNull(),
    totalDeductions: money('total_deductions').notNull(),
    gross: money('gross').notNull(),
    net: money('net').notNull(),
    lines: jsonb('lines').$type<PayslipLine[]>().notNull(),
    snapshot: jsonb('snapshot').$type<Record<string, unknown>>().notNull(), // employee details at time of run
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex('payslips_run_employee_uq').on(t.payrollRunId, t.employeeId), index('payslips_employee_idx').on(t.employeeId)],
);

export const loans = pgTable('loans', {
  id: id(),
  tenantId: tenantId(),
  employeeId: uuid('employee_id')
    .notNull()
    .references(() => employees.id),
  principal: money('principal').notNull(),
  installment: money('installment').notNull(),
  startPeriod: text('start_period').notNull(),
  reason: text('reason'),
  status: text('status', { enum: ['ACTIVE', 'CLOSED'] }).notNull().default('ACTIVE'),
  createdByUserId: uuid('created_by_user_id'),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

