export const kpiTargets = pgTable('kpi_targets', {
  id: id(),
  tenantId: tenantId(),
  employeeId: uuid('employee_id')
    .notNull()
    .references(() => employees.id),
  period: text('period').notNull(),
  metric: text('metric').notNull(),
  unit: text('unit').notNull(),
  targetValue: numeric('target_value', { precision: 16, scale: 2, mode: 'number' }).notNull(),
  incentiveType: text('incentive_type', { enum: ['FIXED', 'PERCENT_OF_EXCESS'] }).notNull(),
  incentiveValue: numeric('incentive_value', { precision: 14, scale: 2, mode: 'number' }).notNull(),
  createdByUserId: uuid('created_by_user_id'),
  createdAt: createdAt(),
});

export const kpiSubmissions = pgTable('kpi_submissions', {
  id: id(),
  tenantId: tenantId(),
  employeeId: uuid('employee_id')
    .notNull()
    .references(() => employees.id),
  targetId: uuid('target_id').references(() => kpiTargets.id),
  period: text('period').notNull(),
  metric: text('metric').notNull(),
  achievedValue: numeric('achieved_value', { precision: 16, scale: 2, mode: 'number' }).notNull(),
  notes: text('notes'),
  tlRemarks: text('tl_remarks'),
  hrRemarks: text('hr_remarks'),
  ...approvalColumns(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

