/* ======================= Audit (F5) & jobs ======================= */

export const auditLogs = pgTable(
  'audit_logs',
  {
    id: bigserial('id', { mode: 'number' }).primaryKey(),
    tenantId: tenantId(),
    actorUserId: uuid('actor_user_id'),
    actorLabel: text('actor_label'),
    action: text('action').notNull(),
    entityType: text('entity_type'),
    entityId: text('entity_id'),
    method: text('method'),
    path: text('path'),
    statusCode: integer('status_code'),
    ip: text('ip'),
    userAgent: text('user_agent'),
    metadata: jsonb('metadata').$type<Record<string, unknown>>(),
    createdAt: createdAt(),
  },
  (t) => [index('audit_logs_tenant_time_idx').on(t.tenantId, t.createdAt), index('audit_logs_entity_idx').on(t.entityType, t.entityId)],
);

/** Background jobs (emails, scheduled tasks). Not tenant-scoped by RLS; payload carries tenantId. */
export const jobs = pgTable(
  'jobs',
  {
    id: id(),
    queue: text('queue').notNull(),
    payload: jsonb('payload').$type<Record<string, unknown>>().notNull(),
    status: text('status', { enum: ['QUEUED', 'RUNNING', 'DONE', 'FAILED'] }).notNull().default('QUEUED'),
    attempts: integer('attempts').notNull().default(0),
    maxAttempts: integer('max_attempts').notNull().default(5),
    runAt: ts('run_at').notNull().defaultNow(),
    lockedAt: ts('locked_at'),
    lastError: text('last_error'),
    dedupeKey: text('dedupe_key').unique(),
    createdAt: createdAt(),
  },
  (t) => [index('jobs_pick_idx').on(t.status, t.runAt).where(sql`status = 'QUEUED'`)],
);

/** Tables without tenant_id RLS (platform + infra). Everything else gets RLS. */
export const NON_TENANT_TABLES = ['tenants', 'jobs'];
